"use strict";
(()=>{const L=window.Lab;if(!L||!L.$('separation-lab'))return;L.init(['time','second'],()=>{const t=L.range('time'),B=L.range('second'),A1=Math.exp(-(Math.PI**2)*t),A2=B*Math.exp(-4*Math.PI**2*t),first=x=>A1*Math.sin(Math.PI*x),second=x=>A2*Math.sin(2*Math.PI*x);L.plot(L.$('drawing'),[{fn:first,color:'#cf604b'},{fn:second,color:'#172a45',dash:'6 5'},{fn:x=>first(x)+second(x)}],{xMax:1,yMin:-1,yMax:2,xLabel:'位置 x（m）；同一時間的空間剖面',yLabel:'溫差 u（K）；各模式與總和'});L.text('result-primary',L.fmt(A1,6)+' K');L.text('result-secondary',L.fmt(A2,6)+' K');L.text('feedback','第一模態衰減率 π²≈'+L.fmt(Math.PI**2)+' s⁻¹，第二為 4π²≈'+L.fmt(4*Math.PI**2)+' s⁻¹，快四倍。時間 '+L.fmt(t)+' s 時，兩個初始幅值 1 K 與 '+L.fmt(B)+' K 分別剩 '+L.fmt(A1,6)+' K、'+L.fmt(A2,6)+' K。兩個正弦在 x=0、1 m 都是零，所以相加後仍滿足同一邊界；任意初形未必只需兩項。');});})();
